#[allow(unused_imports)] use cantrip_api::*;
fn total_power_of(q: &dyn Query, id: ObjectId) -> u64 { i64::from(q.chars(id).power.unwrap_or(0)).max(0) as u64 }
fn total_power(q: &dyn Query, choice: &Choice, most: u32) -> Verdict { let total: u64 = choice.selected.iter().map(|&c| total_power_of(q, c)).sum(); Verdict { complete: total <= u64::from(most), addable: Bits::of(choice.candidates.len(), |i| total + total_power_of(q, choice.candidates[i]) <= u64::from(most)) } }
fn largest_total_power(q: &dyn Query, choice: &Choice, most: u32) -> Vec<ObjectId> { cantrip_api::select::largest_within(choice, |c| total_power_of(q, c), u64::from(most)) }
#[allow(unused_variables)] fn ability_0_target_0(q: &dyn Query, asker: &Asker, t: Target) -> bool { matches!(t, Target::Object(id) if (q.state().obj(id).zone.kind() == ZoneKind::Graveyard) && !q.state().obj(id).token && ((q.chars(id).is(CardType::Creature) && (q.state().obj(id).zone.kind() == ZoneKind::Graveyard && Some(asker.controller) == Some(q.state().obj(id).owner))))) }
static ABILITY_0_TARGETS: &[cantrip_api::TargetSpec] = &[target(ability_0_target_0).between(0, cantrip_api::TargetSpec::ANY_NUMBER).together(cantrip_api::select::set_part(&(total_power as SelectFn), &(largest_total_power as cantrip_api::select::LargestFn), 10, "with total power {n} or less"))];
